CREATE FUNCTION company_private.r60_state_fence() RETURNS trigger
LANGUAGE plpgsql SECURITY INVOKER SET search_path=pg_catalog AS $$
BEGIN
 IF TG_OP='DELETE' THEN RAISE EXCEPTION 'R60_IMMUTABLE_HISTORY'; END IF;
 IF TG_TABLE_NAME='r60_engine_streams' THEN
  IF (to_jsonb(OLD)-'next_sequence') IS DISTINCT FROM (to_jsonb(NEW)-'next_sequence') OR NEW.next_sequence<>OLD.next_sequence+1 THEN RAISE EXCEPTION 'R60_SEQUENCE_IMMUTABLE'; END IF;
 ELSIF TG_TABLE_NAME='r60_tool_consumptions' THEN
  IF (to_jsonb(OLD)-ARRAY['state','effect_attestation_id']) IS DISTINCT FROM (to_jsonb(NEW)-ARRAY['state','effect_attestation_id']) OR OLD.state<>'CONSUMED' OR OLD.effect_attestation_id IS NOT NULL OR NOT ((NEW.state='SUCCEEDED' AND NEW.effect_attestation_id IS NOT NULL) OR (NEW.state='UNKNOWN' AND NEW.effect_attestation_id IS NULL)) THEN RAISE EXCEPTION 'R60_ONE_USE_EFFECT_STATE'; END IF;
 ELSIF TG_TABLE_NAME='r60_lease_extensions' THEN
  IF (to_jsonb(OLD)-ARRAY['state','prepared_attestation_id','active_attestation_id']) IS DISTINCT FROM (to_jsonb(NEW)-ARRAY['state','prepared_attestation_id','active_attestation_id']) OR NOT ((OLD.state='PREPARED' AND NEW.state='COMMITTED' AND OLD.prepared_attestation_id IS NULL AND NEW.prepared_attestation_id IS NOT NULL AND NEW.active_attestation_id IS NULL) OR (OLD.state='COMMITTED' AND NEW.state='ACTIVE' AND NEW.prepared_attestation_id IS NOT DISTINCT FROM OLD.prepared_attestation_id AND NEW.active_attestation_id IS NOT NULL)) THEN RAISE EXCEPTION 'R60_LEASE_HANDSHAKE_STATE'; END IF;
 ELSE RAISE EXCEPTION 'R60_UNKNOWN_METADATA_TABLE'; END IF;
 RETURN NEW;
END $$;
CREATE TRIGGER r60_state_fence BEFORE UPDATE OR DELETE ON company_private.r60_engine_streams FOR EACH ROW EXECUTE FUNCTION company_private.r60_state_fence();
CREATE TRIGGER r60_state_fence BEFORE UPDATE OR DELETE ON company_private.r60_tool_consumptions FOR EACH ROW EXECUTE FUNCTION company_private.r60_state_fence();
CREATE TRIGGER r60_state_fence BEFORE UPDATE OR DELETE ON company_private.r60_lease_extensions FOR EACH ROW EXECUTE FUNCTION company_private.r60_state_fence();
